function callApi(string $path,mixed $body=null,?string $key=null,string $user='operator',string $password='shipping-smoke'):array {global $base;$c=curl_init($base.'/api/'.$path);$headers=['Content-Type: application/json'];if($user!=='')$headers[]='Authorization: Basic '.base64_encode($user.':'.$password);if($key!==null)$headers[]='Idempotency-Key: '.$key;curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_HTTPHEADER=>$headers]);if($body!==null||$key!==null&&str_starts_with($key,'invalid-'))curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>($body===[]&&($key===null||!str_starts_with($key,'invalid-'))?'{}':json_encode(is_array($body)&&!array_is_list($body)?(object)$body:$body,JSON_THROW_ON_ERROR|JSON_PRESERVE_ZERO_FRACTION))]);$raw=curl_exec($c);$code=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);return [$code,is_string($raw)?json_decode($raw,true):null];}
